function Datasets({ project, datasets, contacts, jobs }: { project: string; datasets: SFTDataset[]; contacts: ContactStats[]; jobs: SFTJob[] }) {
  const { privacyMode } = usePrivacyMode();
  const { perform } = useUI();
  const [preparing, setPreparing] = useState(false), [source, setSource] = useState('chats'), [scopeMode, setScopeMode] = useState<'selected' | 'all'>('selected'), [name, setName] = useState(''), [from, setFrom] = useState(''), [to, setTo] = useState(''), [selected, setSelected] = useState<string[]>([]), [search, setSearch] = useState(''), [jsonl, setJSONL] = useState(''), [filename, setFilename] = useState('');
  const [reviewing, setReviewing] = useState(''); const fileRef = useRef<HTMLInputElement>(null);
  const review = datasets.find(d => d.id === reviewing);
  const availableContacts = contacts.filter(c => !c.username.includes('@chatroom'));
  const visibleContacts = availableContacts.filter(c => `${c.remark || ''} ${c.nickname || ''}`.toLocaleLowerCase().includes(search.toLocaleLowerCase())).slice(0, 100);
  if (review) return <SampleReview dataset={review} onClose={() => setReviewing('')} />;
  if (preparing) return <section className="sft-card sft-form sft-prepare"><div className="sft-row"><div><h2>准备训练数据</h2><p className="sft-muted">先生成可检查的草稿，不会立即开始训练。</p></div><Button onClick={() => setPreparing(false)}><ArrowLeft size={15} />返回数据版本</Button></div>
    <div className="sft-prepare-example"><strong>一条训练样本是什么？</strong><p>对方：周末去散步吗？<br />我的回复：好呀，天气好就出门！</p><span>模型阅读聊天上下文，学习最后这条“我的回复”；不是训练对方的说话方式。</span></div>
    <div><h3>1. 选择数据来源</h3><p className="sft-muted">想用 WeLink 里的聊天，选第一项；已有训练文件时再选择导入。</p><div className="sft-choice-grid"><button type="button" aria-pressed={source === 'chats'} onClick={() => setSource('chats')}><strong>使用我的私聊</strong><span>从当前账号的聊天记录生成样本</span></button><button type="button" aria-pressed={source === 'jsonl'} onClick={() => setSource('jsonl')}><strong>导入训练文件</strong><span>使用已有的 JSONL 对话样本</span></button></div></div>
    <Field label="数据名称（选填）" hint="方便以后辨认；不填写会使用创建时间。"><input placeholder="例如：和朋友的日常聊天" value={name} maxLength={80} onChange={e => setName(e.target.value)} /></Field>
    {source === 'chats' ? <><div><h3>2. 选择聊天范围</h3><p className="sft-muted">建议先选择你愿意用于训练的联系人。系统只使用私聊，每位联系人最多保留 200 条样本。</p><div className="sft-choice-grid"><button type="button" aria-pressed={scopeMode === 'selected'} onClick={() => setScopeMode('selected')}><strong>指定联系人（推荐）</strong><span>只使用下方选中的私聊</span></button><button type="button" aria-pressed={scopeMode === 'all'} onClick={() => setScopeMode('all')}><strong>全部可用私聊</strong><span>使用所有符合条件的联系人，排除已屏蔽联系人</span></button></div></div>
      {scopeMode === 'selected' ? <div className="sft-form"><div className="sft-row"><h3>选择联系人</h3><span className="sft-muted">已选择 {selected.length} 位</span></div><input aria-label="搜索联系人" placeholder="搜索联系人…" value={search} onChange={e => setSearch(e.target.value)} />{visibleContacts.length ? <div className="sft-contact-list">{visibleContacts.map(c => <button type="button" key={c.username} aria-pressed={selected.includes(c.username)} onClick={() => setSelected(old => old.includes(c.username) ? old.filter(x => x !== c.username) : [...old, c.username])}><Avatar contact={c} name={c.remark || c.nickname || c.username} className={`h-8 w-8 ${privacyMode ? 'privacy-blur' : ''}`} /><span className={privacyMode ? 'privacy-blur' : undefined}>{c.remark || c.nickname || c.username}</span>{selected.includes(c.username) && <Check size={15} />}</button>)}</div> : <p className="sft-muted">{availableContacts.length ? '没有匹配的联系人，请更换搜索词。' : '没有可选择的私聊联系人，请先检查聊天数据是否已连接并完成分析。'}</p>}{!selected.length && <p className="sft-note">请至少选择一位联系人；未选择时不会自动使用全部私聊。</p>}</div> : <p className="sft-note">将使用当前账号全部符合条件的私聊。已屏蔽的联系人及没有本人回复的联系人不会参与。</p>}
      <div><h3>3. 选择时间范围（选填）</h3><p className="sft-muted">留空表示不限时间，只使用此范围内的聊天。</p><div className="sft-form-grid"><Field label="起始日期"><DatePicker value={from} onValueChange={setFrom} max={to || undefined} placeholder="不限起始日期" /></Field><Field label="结束日期"><DatePicker value={to} onValueChange={setTo} min={from || undefined} placeholder="不限结束日期" /></Field></div></div></> : <div className="sft-import"><Upload size={20} /><h3>2. 选择 JSONL 文件</h3><p className="sft-muted">每行是一条对话样本；最后一条 assistant 是希望模型学习的回复。支持 messages 或 instruction / output 格式，最多 32 MB / 20,000 条。</p><pre className="sft-code">{'{"messages":[{"role":"user","content":"周末去散步吗？"},{"role":"assistant","content":"好呀！"}]}'}</pre><input ref={fileRef} type="file" accept=".jsonl,.json,application/json" className="sr-only" onChange={e => { const f = e.target.files?.[0]; if (f) void perform(async () => { if (f.size > 32 * 1024 ** 2) throw new Error('文件超过 32 MB'); const text = await f.text(); if (!text.trim()) throw new Error('文件为空'); setJSONL(text); setFilename(f.name); }); }} /><Button onClick={() => fileRef.current?.click()}>{filename || '选择 JSONL 文件'}</Button></div>}
    <div className="sft-note"><strong>接下来会发生什么？</strong><br />系统生成一份数据草稿，你可以查看、编辑和排除样本，再手动冻结用于训练。原始聊天不会被修改。系统只做基础脱敏，请自行检查敏感内容；草稿保存在 WeLink 的 SFT 存储中，预检和训练时样本会发送到所选训练机。</div>
    <Button primary disabled={source === 'jsonl' ? !jsonl : scopeMode === 'selected' && !selected.length} onClick={() => void perform(async () => { await sftApi.createDataset(project, { name, scope: { contacts: source === 'chats' && scopeMode === 'selected' ? selected : [], from: source === 'chats' && from ? Math.floor(new Date(`${from}T00:00:00`).getTime() / 1000) : 0, to: source === 'chats' && to ? Math.floor(new Date(`${to}T23:59:59`).getTime() / 1000) : 0 }, ...(source === 'jsonl' ? { jsonl } : {}) }); setPreparing(false); }, '已开始生成数据草稿，完成后请审核并冻结')}>生成待审核草稿<ArrowRight size={15} /></Button>
  </section>;
  return <section><div className="sft-section-heading"><div><h2>数据版本</h2><p>每个版本是一组训练样本。先选择聊天范围并生成草稿，检查内容后冻结；冻结后的版本用于训练和评测，不会再改变。</p></div><Button primary disabled={datasets.some(d => d.state === 'building')} onClick={() => setPreparing(true)}><Plus size={15} />准备数据</Button></div>
    {!datasets.length ? <Empty title="从一份干净的数据开始">支持私聊和 JSONL。正式训练至少需要训练 / 验证 / 测试集 500 / 50 / 50 条；短训验证为 100 / 10 / 10 条，且需要足够独立会话。</Empty> : <div className="sft-list">{datasets.map(d => <article key={d.id} className="sft-card"><div className="sft-row"><div><h3>{d.name}</h3><span className="sft-muted">{date(d.created_at)} · {d.pipeline}</span></div><Status value={d.state} /></div>{d.report && <div className="sft-data-numbers"><span><strong>{d.report.raw.toLocaleString()}</strong>原始消息 / 导入行</span><span><strong>{d.report.kept.toLocaleString()}</strong>保留样本</span><span><strong>{d.state === 'frozen' ? `${d.report.splits.train || 0} / ${d.report.splits.valid || 0} / ${d.report.splits.test || 0}` : d.report.unreviewed.toLocaleString()}</strong>{d.state === 'frozen' ? '训练 / 验证 / 测试' : '待抽查样本'}</span></div>}{d.state === 'failed' && <p className="sft-error-text">{jobs.find(j => j.kind === 'dataset' && j.result?.dataset_id === d.id)?.error || '准备中断，请重新构建数据草稿。'}</p>}<div className="sft-actions">{d.state === 'building' && <Button onClick={() => void perform(async () => { const job = jobs.find(j => j.kind === 'dataset' && j.result?.dataset_id === d.id); if (job) await sftApi.cancel(job.id); }, '已请求停止数据准备')}>停止准备</Button>}{['draft', 'frozen'].includes(d.state) && <Button onClick={() => setReviewing(d.id)}>{d.state === 'frozen' ? '查看样本与报告' : '审核样本'}<ArrowRight size={14} /></Button>}{d.state === 'frozen' && <Button onClick={() => void perform(() => sftApi.download(`/dataset-versions/${d.id}/export`, 'welink-sft-dataset.zip'))}><Download size={14} />导出数据</Button>}{d.state === 'frozen' && <Button onClick={() => void perform(() => sftApi.fork(d.id), '已从冻结版本创建独立草稿，原版本保持不变')}>基于此版创建草稿</Button>}</div>{d.sha256 && <p className="sft-hash">SHA-256 {d.sha256}</p>}</article>)}</div>}
  </section>;
}

function SampleReview({ dataset: d, onClose }: { dataset: SFTDataset; onClose: () => void }) {
  const { privacyMode } = usePrivacyMode();
  const { perform, busy } = useUI(); const [samples, setSamples] = useState<SFTSample[]>([]), [total, setTotal] = useState(0), [offset, setOffset] = useState(0), [filter, setFilter] = useState('all'), [localError, setLocalError] = useState(''), [editing, setEditing] = useState<SFTSample>(), [edited, setEdited] = useState<SFTMessage[]>([]), [freeze, setFreeze] = useState(false);
  useEffect(() => { let active = true; void sftApi.samples(d.id, offset, ['pending', 'kept', 'excluded'].includes(filter) ? filter : '', filter === 'issues').then(r => { if (active) { setSamples(r.samples); setTotal(r.total); setLocalError(''); } }).catch(e => { if (active) setLocalError(e.message); }); return () => { active = false; }; }, [d.id, d.revision, offset, filter]);
  const review = (ids: string[], action: string, messages?: SFTMessage[]) => perform(() => sftApi.review(d.id, { revision: d.revision, ids, action, messages }), '草稿审核已保存');
  return <section><div className="sft-section-heading"><div><Button onClick={onClose}><ArrowLeft size={14} />版本列表</Button><h2 className="mt-3">{d.name}</h2><p>最后一条绿色标记为训练目标；历史回复只作上下文。所有编辑只修改草稿。</p></div>{d.state === 'draft' ? <Button primary onClick={() => setFreeze(true)}>冻结版本<Check size={15} /></Button> : <Status value="frozen" />}</div><div className="sft-review-layout"><aside className="sft-card sft-report"><h3>数据质量报告</h3><dl><dt>原始记录</dt><dd>{d.report.raw}</dd><dt>候选样本</dt><dd>{d.report.candidates}</dd><dt>保留样本</dt><dd>{d.report.kept}</dd>{Object.entries(d.report.excluded || {}).map(([key, value]) => <div key={key}><dt>{key}</dt><dd>{value}</dd></div>)}</dl><h4>集合划分</h4><p className="sft-muted">{d.state === 'frozen' ? `训练 ${d.report.splits.train || 0} · 验证 ${d.report.splits.valid || 0} · 测试 ${d.report.splits.test || 0}` : '冻结时按完整会话、来源消息和重复簇分组；默认 80% / 10% / 10%。'}</p><h4>贡献分布</h4>{Object.entries(d.report.contributions || {}).slice(0, 20).map(([key, n]) => <div className="sft-row sft-muted" key={key}><span>匿名联系人 {key.slice(0, 6)}</span><span>{n} 条</span></div>)}</aside><div className="sft-form"><div className="sft-row"><Select aria-label="样本筛选" value={filter} onValueChange={v => { setFilter(v); setOffset(0); }} options={[{ value: 'all', label: '全部样本' }, { value: 'issues', label: '需要复核的脱敏样本' }, { value: 'pending', label: '尚未抽查' }, { value: 'kept', label: '已保留' }, { value: 'excluded', label: '已排除' }]} />{d.state === 'draft' && <Button disabled={!samples.length} onClick={() => void review(samples.map(s => s.id), 'keep')}>保留本页 {samples.length} 条</Button>}</div>{localError && <p role="alert" className="sft-error-text">{localError}</p>}{!samples.length && <Empty title="没有匹配的样本">可以调整筛选条件，或返回准备更多数据。</Empty>}{samples.map(s => <article className="sft-card sft-sample" key={s.id}><div className="sft-row"><span className="sft-muted">匿名联系人 {s.contact.slice(0, 6)} · {s.split || (s.review === 'kept' ? '已保留' : s.review === 'excluded' ? '已排除' : '待抽查')}</span><span className="sft-hash">{short(s.id)}</span></div>{s.issues?.map(issue => <p className="sft-note" key={issue}>{issue}</p>)}{s.messages.map((m, i) => <div className={`sft-message ${i === s.messages.length - 1 ? 'sft-target' : ''}`} key={i}><span>{m.role === 'system' ? '系统' : m.role === 'user' ? '对方' : i === s.messages.length - 1 ? '我的目标回复' : '我的历史回复'}</span><p className={privacyMode ? 'privacy-blur' : undefined}>{m.content}</p></div>)}{d.state === 'draft' && <div className="sft-actions"><Button onClick={() => void review([s.id], 'keep')}>保留</Button><Button onClick={() => void review([s.id], 'exclude')}>排除</Button><Button onClick={() => { setEditing(s); setEdited(s.messages.map(m => ({ ...m }))); }}>编辑脱敏文本</Button><Button disabled={s.review === 'pending'} onClick={() => void review([s.id], 'reset')}>撤销审核</Button></div>}</article>)}<div className="sft-row"><span className="sft-muted">共 {total} 条 · 第 {Math.floor(offset / 20) + 1} 页</span><div className="sft-actions"><Button disabled={offset === 0} onClick={() => setOffset(Math.max(0, offset - 20))}>上一页</Button><Button disabled={offset + 20 >= total} onClick={() => setOffset(offset + 20)}>下一页</Button></div></div></div></div>
    <Dialog open={!!editing} title="编辑样本文本" onClose={() => setEditing(undefined)}><div className="sft-page sft-form">{edited.map((m, i) => <Field key={i} label={m.role === 'user' ? '对方输入' : m.role === 'system' ? '系统提示' : '我的回复'}><textarea rows={3} value={m.content} onChange={e => setEdited(old => old.map((item, index) => index === i ? { ...item, content: e.target.value } : item))} /></Field>)}<p className="sft-muted">保存会执行一次基础脱敏，并将此条标记为已复核。请确认没有姓名、地址或其他不希望保留的信息。</p><Button primary disabled={busy || edited.some(m => !m.content.trim())} onClick={() => void (async () => { if (editing && await review([editing.id], 'keep', edited)) setEditing(undefined); })()}>保存并保留</Button></div></Dialog>
    <Dialog open={freeze} title="冻结数据版本" onClose={() => setFreeze(false)}><div className="sft-page sft-form"><p>将保留的 {d.report.kept} 条样本编译为只读版本。脱敏问题必须复核；干净样本可抽查后冻结。冻结后不能再编辑此版本。</p><p className="sft-muted">未达到训练门槛的版本仍可导出，训练按钮会说明缺少的独立样本数。请确认已检查个人隐私和回复角色。</p><Button primary onClick={() => void perform(async () => { await sftApi.freeze(d); setFreeze(false); }, '数据已冻结，版本内容和划分已保存校验和')}>确认冻结</Button></div></Dialog>
  </section>;
}

function Environments({ project, workers }: { project: string; workers: SFTWorker[] }) {
  const { perform } = useUI(); const [pairing, setPairing] = useState<{ code: string; expires_at: number }>(), [kind, setKind] = useState('mac');
  const [localServer, setLocalServer] = useState(getServerURL() || window.location.origin), [gpuServer, setGpuServer] = useState('');
  const server = (kind === 'gpu' ? gpuServer : localServer).trim();
  let serverValid = false;
  try {
    const url = new URL(server);
    serverValid = !url.username && !url.password && !url.search && !url.hash && (url.protocol === 'https:' || (url.protocol === 'http:' && ['localhost', '127.0.0.1', '[::1]'].includes(url.hostname)));
  } catch { /* 地址不完整时显示提示 */ }
  const quotedServer = "'" + server.replace(/'/g, "'\"'\"'") + "'";
  return <div className="sft-form"><p className="sft-muted">Mac 使用原生 arm64 Python 和 Metal；GPU 训练机使用 Linux / NVIDIA CUDA。worker 仅接收当前项目授权的任务，关闭浏览器不会停止训练。</p><div className="sft-env-grid">{workers.map(w => <article className="sft-card" key={w.id}><div className="sft-row"><h3 className="sft-inline">{w.capabilities.os === 'Darwin' ? <Monitor size={17} /> : <Server size={17} />}{w.name}</h3><Status value={w.revoked ? 'stopped' : Date.now() / 1000 - w.last_seen < 45 ? 'online' : 'offline'} /></div><p className="sft-muted">{w.capabilities.os} / {w.capabilities.arch} · 心跳 {date(w.last_seen)}</p><p className="sft-muted">磁盘可用 {bytes(w.capabilities.free_disk_bytes)}</p>{Object.entries(w.capabilities.engines || {}).map(([engine, capability]) => <p className="sft-muted" key={engine}>{engine === 'mlx' ? 'MLX' : 'LLaMA-Factory'}：{capability.available ? '依赖和设备可用，模型仍需预检' : capability.reason}</p>)}{w.capabilities.devices?.map(d => <p key={d.id}>{d.name}{d.free_bytes ? ` · 可用 ${bytes(d.free_bytes)}` : ''}</p>)}{!w.revoked && <Button onClick={() => void perform(() => sftApi.revoke(w.id), '环境授权已撤销，worker 将请求当前任务保存并停止')}>撤销此项目授权</Button>}</article>)}</div>
    <section className="sft-card sft-form"><div><h3>连接新的训练环境</h3><p className="sft-muted">WeLink 负责准备数据和管理任务；训练机运行 Worker 接收任务并使用 GPU。启动训练前会将选定样本发送到该训练机，请只连接可信环境。</p></div><Select aria-label="环境类型" value={kind} onValueChange={value => { setKind(value); setPairing(undefined); }} options={[{ value: 'mac', label: '本机 Apple Silicon Mac · MLX' }, { value: 'gpu', label: '远程 Linux / NVIDIA GPU 容器' }]} />
      <div><h4>1. 在{kind === 'gpu' ? 'GPU 容器或训练机' : '本机'}安装 Worker</h4><p className="sft-muted">先准备 Python 3.12 和 WeLink 仓库中的 workers/sft 目录。{kind === 'gpu' ? '容器需要能运行 nvidia-smi、访问依赖源和模型文件。' : '需要原生 arm64 Python 和 macOS 14 或更新版本。'}以下命令在训练环境的仓库根目录执行；依赖安装到独立虚拟环境。</p></div><pre className="sft-code">{`python3.12 -m venv ~/.local/share/welink-sft/venv\n~/.local/share/welink-sft/venv/bin/pip install --require-hashes -r workers/sft/requirements-${kind === 'mac' ? 'mlx' : 'cuda'}.lock\n~/.local/share/welink-sft/venv/bin/pip install ./workers/sft\n~/.local/share/welink-sft/venv/bin/welink-sft doctor`}</pre>
      <div><h4>2. 填写训练环境能够访问的 WeLink 地址</h4>{kind === 'gpu' ? <><p className="sft-muted">在 GPU 容器里访问的地址可能和浏览器不同：容器里的 127.0.0.1 指向容器自身，不是你的电脑。请使用已正确配置的 HTTPS 代理，或先建立安全隧道。</p><div className="sft-note">例如，从训练环境通过 SSH 隧道访问 WeLink 后端：<br /><code>ssh -N -L 18080:127.0.0.1:8088 &lt;WeLink主机SSH地址&gt;</code><br />将 8088 换成 WeLink 主机上实际的后端端口；保持隧道运行后，在下方填写 <code>http://127.0.0.1:18080</code>。需要训练环境能够 SSH 到该主机。</div><p className="sft-muted">HTTPS 代理需将 /api/sft-worker/ 直接转发到后端，并按部署文档设置可信代理 IP。远程 HTTP 地址不受支持。</p></> : <p className="sft-muted">填写本机 Worker 可访问的 WeLink 控制端地址；HTTP 只允许原生后端收到的本机回环连接。</p>}</div>
      <Field label={kind === 'gpu' ? '训练容器可访问的 WeLink 地址' : '本机 Worker 可访问的 WeLink 地址'} hint="支持 HTTPS；HTTP 仅支持通过安全隧道或本机回环访问。"><input value={kind === 'gpu' ? gpuServer : localServer} onChange={e => { if (kind === 'gpu') setGpuServer(e.target.value); else setLocalServer(e.target.value); }} placeholder={kind === 'gpu' ? 'https://你的WeLink地址 或 http://127.0.0.1:18080' : 'http://127.0.0.1:8080'} /></Field>
      {server && !serverValid && <p className="sft-error-text" role="status">请输入不含凭据、查询参数或片段的 HTTPS 地址，或本机回环 HTTP 地址。</p>}
      <div><h4>3. 生成配对码并启动 Worker</h4><p className="sft-muted">配对码只绑定当前项目，有效期 10 分钟。Worker 运行后会显示在上方；关闭网页不会停止 Worker。</p></div><Button primary disabled={!project || !serverValid} onClick={() => void perform(async () => setPairing(await sftApi.pairing(project)))}>生成一次性配对码</Button>{!project && <p className="sft-muted">先创建项目，再授权训练环境。</p>}{pairing && <><Field label={`一次性配对码 · ${date(pairing.expires_at)} 过期`}><input readOnly value={pairing.code} aria-label="一次性配对码" onFocus={e => e.target.select()} /></Field><pre className="sft-code">{`~/.local/share/welink-sft/venv/bin/welink-sft pair --server ${quotedServer}\n# 在训练环境中按提示输入配对码，再启动：\n~/.local/share/welink-sft/venv/bin/welink-sft run`}</pre><p className="sft-muted">配对凭据保存在训练环境的 0600 文件；不要分享配对码或凭据。预检时才会下载模型，运行记录和训练产物也保存在训练环境。</p></>}</section>
  </div>;
}

function TrainingWizard({ datasets, workers, jobs, onClose, onSubmitted }: { datasets: SFTDataset[]; workers: SFTWorker[]; jobs: SFTJob[]; onClose: () => void; onSubmitted: () => void }) {
  const { perform } = useUI(); const [step, setStep] = useState(0), [preflight, setPreflight] = useState('');
  const [config, setConfig] = useState<SFTConfig>({ dataset_id: datasets.find(d => d.state === 'frozen')?.id || '', worker_id: workers[0]?.id || '', engine: workers[0]?.capabilities.engines.mlx?.available ? 'mlx' : 'llamafactory', model: '', revision: '', template: '', preset: 'validation', max_steps: 100, max_seconds: 3600, sequence_length: 2048, learning_rate: 1e-4, rank: 16, gradient_accumulation: 8, seed: 42, gpu: '0' });
  const change = <K extends keyof SFTConfig>(key: K, value: SFTConfig[K]) => { setConfig(old => ({ ...old, [key]: value })); setPreflight(''); };
  const worker = workers.find(w => w.id === config.worker_id), dataset = datasets.find(d => d.id === config.dataset_id), check = jobs.find(j => j.id === preflight);
  const minimum = config.preset === 'validation' ? [100, 10, 10] : [500, 50, 50];
  const dataReady = !!dataset && ['train', 'valid', 'test'].every((key, i) => (dataset.report.splits[key] || 0) >= minimum[i]);
  const limitsReady = config.max_seconds >= 60 && config.max_seconds <= 86400 && config.max_steps >= 1 && config.max_steps <= 100000 && config.sequence_length >= 128 && config.sequence_length <= 8192 && config.rank >= 1 && config.rank <= 128 && config.learning_rate >= 1e-7 && config.learning_rate <= .01 && config.gradient_accumulation >= 1 && config.gradient_accumulation <= 64;
  const configReady = !!worker?.capabilities.engines[config.engine]?.available && /^[\w.-]+\/[\w.-]+$/.test(config.model) && /^[a-f\d]{40,64}$/i.test(config.revision) && (config.engine !== 'llamafactory' || !!config.template);
  return <section className="sft-card sft-form"><div className="sft-row"><h2>新建训练</h2><Button onClick={onClose}>返回任务列表</Button></div><ol className="sft-wizard-steps">{['选数据', '选环境与模型', '配置与预检', '确认提交'].map((label, i) => <li key={label} aria-current={step === i ? 'step' : undefined}><span>{i + 1}</span>{label}</li>)}</ol>
    {step === 0 && <><Field label="冻结数据版本"><Select value={config.dataset_id} onValueChange={v => change('dataset_id', v)} options={datasets.filter(d => d.state === 'frozen').map(d => ({ value: d.id, label: `${d.name} · ${d.report.kept} 条` }))} /></Field>{dataset && <div className="sft-note">训练 {dataset.report.splits.train || 0} / 验证 {dataset.report.splits.valid || 0} / 测试 {dataset.report.splits.test || 0} 条<br />SHA-256 {dataset.sha256.slice(0, 16)}…</div>}<Field label="训练预设"><Select value={config.preset} onValueChange={v => { change('preset', v); change('max_steps', v === 'validation' ? 100 : 1000); }} options={[{ value: 'validation', label: '短训验证 · 验证环境和流程，结果仅供试用' }, { value: 'standard', label: '标准训练 · 最多 1 epoch，并受 step 上限约束' }]} /></Field>{!dataReady && <p className="sft-error-text">此预设至少需要 {minimum.join(' / ')} 条独立训练 / 验证 / 测试样本。</p>}</>}
    {step === 1 && <><Field label="运行环境"><Select value={config.worker_id} onValueChange={v => { change('worker_id', v); const w = workers.find(w => w.id === v); change('engine', w?.capabilities.engines.mlx?.available ? 'mlx' : 'llamafactory'); }} options={workers.map(w => ({ value: w.id, label: `${w.name} · ${w.capabilities.os} / ${w.capabilities.arch}` }))} /></Field><Field label="执行器"><Select value={config.engine} onValueChange={v => change('engine', v)} options={[{ value: 'mlx', label: 'MLX · LoRA', disabled: !worker?.capabilities.engines.mlx?.available }, { value: 'llamafactory', label: 'LLaMA-Factory · LoRA', disabled: !worker?.capabilities.engines.llamafactory?.available }]} /></Field><Field label="基础模型 ID" hint="填写与执行器兼容的 Hugging Face 模型，例如组织名/模型名；聊天 API 的模型名不能直接用于训练。"><input value={config.model} placeholder="组织名/模型名" onChange={e => change('model', e.target.value.trim())} /></Field><Field label="精确 commit revision" hint="在模型仓库的 Files and versions 中复制 commit hash，不能填写 main。首次预检会下载这个固定版本。"><input value={config.revision} placeholder="40 位或 64 位 commit hash" onChange={e => change('revision', e.target.value.trim())} /></Field>{config.engine === 'llamafactory' && <div className="sft-form-grid"><Field label="Chat template" hint="必须与所选模型对应；预检会校验实际 token labels。"><input value={config.template} placeholder="如：qwen3_nothink" onChange={e => change('template', e.target.value.trim())} /></Field><Field label="指定 GPU"><Select value={config.gpu} onValueChange={v => change('gpu', v)} options={(worker?.capabilities.devices || []).map(d => ({ value: d.id, label: `${d.id} · ${d.name}` }))} /></Field></div>}<p className="sft-muted">权重许可和访问权限由模型来源决定。需要登录的模型应在训练机预先配置 Hugging Face 凭据；WeLink 不接收这些凭据。</p></>}
    {step === 2 && <><div className="sft-form-grid"><Field label="运行时长上限（分钟）"><input type="number" min={1} max={1440} value={config.max_seconds / 60} onChange={e => change('max_seconds', Number(e.target.value) * 60)} /></Field><Field label="Optimizer step 上限"><input type="number" min={1} max={100000} value={config.max_steps} onChange={e => change('max_steps', Number(e.target.value))} /></Field></div><details className="sft-details"><summary>高级训练参数</summary><div className="sft-form-grid">{([['sequence_length', '序列上限', 128, 8192, 128], ['gradient_accumulation', '梯度累积', 1, 64, 1], ['rank', 'LoRA rank', 1, 128, 1], ['learning_rate', '学习率', 0.0000001, 0.01, 0.00001], ['seed', '随机种子', 1, 2147483647, 1]] as const).map(([key, label, min, max, increment]) => <Field label={label} key={key}><input type="number" min={min} max={max} step={increment} value={config[key]} onChange={e => change(key, Number(e.target.value))} /></Field>)}</div><p className="sft-muted">micro batch 固定为 1，packing 关闭，仅监督最终回复。MLX 的 iterations 会按梯度累积换算，实际计划以预检返回为准。</p></details><div className="sft-note">预检会下载模型、校验完整回复与监督标签，并运行两次真实 optimizer updates。原始私聊样本将发送到 <strong>{worker?.name}</strong>；预检权重不会成为正式模型。</div><Button disabled={!configReady || !dataReady || !limitsReady || (!!check && !done(check.state))} onClick={() => void perform(async () => { const j = await sftApi.preflight(config); setConfig(j.config); setPreflight(j.id); }, '已提交预检，结果会自动更新')}>运行环境与模型预检</Button>{check && <div className="sft-card"><div className="sft-row"><h3>预检 {short(check.id)}</h3><Status value={check.state} /></div>{check.error && <p className="sft-error-text">{check.error}</p>}{check.state === 'succeeded' && <p>模型、模板和标签已校验，资源试跑通过。可进入提交摘要。</p>}<p className="sft-muted">{check.state === 'queued' ? '等待环境空闲；已启动的推理服务会占用同一资源，请先在模型页停用。' : !done(check.state) ? 'worker 正在执行真实预检，页面可以安全刷新。' : ''}</p></div>}</>}
    {step === 3 && <><h3>确认训练摘要</h3><dl className="sft-config"><dt>数据</dt><dd>{dataset?.name} · {dataset?.report.kept} 条</dd><dt>环境</dt><dd>{worker?.name} / {config.engine}</dd><dt>基础模型</dt><dd>{config.model}<small>{config.revision}</small></dd><dt>实际计划</dt><dd>{check?.result?.training_plan?.optimizer_steps ?? '未提供'} optimizer steps · micro batch 1</dd><dt>预算</dt><dd>最多 {config.max_steps} optimizer steps / {config.max_seconds / 60} 分钟{config.preset === 'standard' && ' / 1 epoch'}</dd><dt>基础权重</dt><dd>{check?.result?.weight_bytes ? bytes(check.result.weight_bytes) : '预检未提供'}</dd><dt>实测峰值设备内存</dt><dd>{check?.result?.peak_memory_bytes ? bytes(check.result.peak_memory_bytes) : '未提供'}</dd><dt>环境磁盘</dt><dd>可用 {check?.result?.free_disk_bytes ? bytes(check.result.free_disk_bytes) : '未提供'} · 保留空间 {check?.result?.reserved_disk_bytes ? bytes(check.result.reserved_disk_bytes) : '未提供'}</dd><dt>监督与保存</dt><dd>最终本人回复 · 周期保存 · 最近两个恢复点</dd><dt>适用范围</dt><dd>{config.preset === 'validation' ? '短训验证，样本不足，模型仅供试用' : '标准训练，完成后仍需固定测试集评测'}</dd></dl><p className="sft-note">训练成功后不会自动更换默认模型。评测、服务启动和接入均为独立步骤。任务提交后配置固定，后台不会静默调整。</p></>}
    <div className="sft-row"><Button disabled={step === 0} onClick={() => setStep(Math.max(0, step - 1))}><ArrowLeft size={14} />上一步</Button>{step < 3 ? <Button primary disabled={(step === 0 && !dataReady) || (step === 1 && !configReady) || (step === 2 && check?.state !== 'succeeded')} onClick={() => setStep(step + 1)}>下一步<ArrowRight size={14} /></Button> : <Button primary onClick={() => void perform(async () => { await sftApi.train(preflight); onSubmitted(); })}>开始训练</Button>}</div>
  </section>;
}

function Training({ jobs, workers, onNew, ready }: { jobs: SFTJob[]; workers: SFTWorker[]; onNew: () => void; ready: boolean }) {
  const [selected, setSelected] = useState(''); const job = jobs.find(j => j.id === selected);
  if (job) return <JobDetails job={job} worker={workers.find(w => w.id === job.worker_id)} onClose={() => setSelected('')} />;
  const list = jobs.filter(j => j.kind !== 'dataset');
  return <section><div className="sft-section-heading"><div><h2>训练与任务</h2><p>任务持久化保存。进度来自引擎回报，断开页面不会重复启动。</p></div><Button primary disabled={!ready} onClick={onNew}><Plus size={15} />新建训练</Button></div>{!ready && <div className="sft-note">先冻结满足门槛的数据，并在环境管理中连接可用 worker。已启动的推理服务和训练共享资源，需要时请先停用服务。</div>}{!list.length ? <Empty title="还没有训练任务">从短训验证开始，先确认环境、模板和监督标签。</Empty> : <div className="sft-list">{list.map(j => <button type="button" key={j.id} className="sft-card sft-job-row" onClick={() => setSelected(j.id)}><div><h3>{kindNames[j.kind]} · {short(j.id)}</h3><p>{j.config?.model || '数据准备'} · {workers.find(w => w.id === j.worker_id)?.name || '已撤销的环境'}</p><span className="sft-muted">{date(j.created_at)}</span></div><div className="sft-inline"><Status value={j.state} /><ChevronRight size={17} /></div></button>)}</div>}</section>;
}

export function LossChart({ events }: { events: SFTEvent[] }) {
  const points = events.filter(e => e.type === 'metric' && Number.isFinite(e.data.train_loss ?? e.data.loss ?? e.data.val_loss ?? e.data.eval_loss));
  if (!points.length) return <Empty title="等待引擎指标">只有收到真实的 loss 和步数后才绘图。下载与环境准备阶段没有训练百分比。</Empty>;
  const maxStep = Math.max(1, ...points.map(p => Number(p.data.optimizer_step || 0))), losses = points.map(p => Number(p.data.train_loss ?? p.data.loss ?? p.data.val_loss ?? p.data.eval_loss)), min = Math.min(...losses), max = Math.max(min + 0.01, ...losses);
  const line = (validation: boolean) => points.filter(p => validation ? p.data.val_loss !== undefined || p.data.eval_loss !== undefined : p.data.train_loss !== undefined || p.data.loss !== undefined).map(p => `${30 + Number(p.data.optimizer_step || 0) / maxStep * 550},${170 - ((p.data.train_loss ?? p.data.loss ?? p.data.val_loss ?? p.data.eval_loss) - min) / (max - min) * 140}`).join(' ');
  return <div className="sft-chart"><svg viewBox="0 0 610 205" role="img" aria-label={`损失曲线，${points.length} 个真实指标点，范围 ${min.toFixed(3)} 到 ${max.toFixed(3)}`}><path d="M30 20V175H590" fill="none" stroke="var(--border-strong)" /><polyline points={line(false)} fill="none" stroke="var(--accent)" strokeWidth="2" /><polyline points={line(true)} fill="none" stroke="var(--text-secondary)" strokeWidth="2" strokeDasharray="5 4" /><text x="30" y="198">0</text><text x="500" y="198">{maxStep} steps</text></svg><div className="sft-muted">实线：训练 loss · 虚线：验证 loss。不同引擎或数据版本的数值不直接比较。</div><details className="sft-details"><summary>查看指标表格（最近 30 条）</summary><div className="sft-table-scroll"><table><thead><tr><th>Optimizer step</th><th>训练 loss</th><th>验证 loss</th></tr></thead><tbody>{points.slice(-30).map(p => <tr key={p.seq}><td>{p.data.optimizer_step ?? '未提供'}</td><td>{p.data.train_loss ?? p.data.loss ?? '—'}</td><td>{p.data.val_loss ?? p.data.eval_loss ?? '—'}</td></tr>)}</tbody></table></div></details></div>;
}
function JobDetails({ job, worker, onClose }: { job: SFTJob; worker?: SFTWorker; onClose: () => void }) {
  const { perform } = useUI(); const [events, setEvents] = useState<SFTEvent[]>([]), [artifacts, setArtifacts] = useState<SFTArtifact[]>([]), [cancel, setCancel] = useState(false), [error, setError] = useState(''); const cursor = useRef(0);
  useEffect(() => { let alive = true; cursor.current = 0; setEvents([]); const read = async () => { try { const e = await sftApi.events(job.id, cursor.current); if (!alive) return; cursor.current = e.at(-1)?.seq || cursor.current; setEvents(prev => [...prev, ...e].slice(-10000)); setArtifacts(await sftApi.checkpoints(job.id)); } catch (e) { if (alive) setError(e instanceof Error ? e.message : '读取事件失败'); } }; void read(); const timer = setInterval(() => void read(), 4000); return () => { alive = false; clearInterval(timer); }; }, [job.id]);
  const metrics = [...events].reverse().find(e => e.type === 'metric')?.data;
  const currentStep = [...events].reverse().find(e => Number.isFinite(e.data.optimizer_step))?.data.optimizer_step;
  const totalSteps = [...events].reverse().find(e => Number.isFinite(e.data.total_optimizer_steps ?? e.data.optimizer_steps))?.data;
  const offline = !worker || Date.now() / 1000 - worker.last_seen > 45;
  return <section className="sft-form"><div className="sft-section-heading"><div><Button onClick={onClose}><ArrowLeft size={14} />任务列表</Button><h2 className="mt-3">{kindNames[job.kind]} · {short(job.id)}</h2><p>{worker?.name || '环境未连接'} · {date(job.created_at)}</p></div><div className="sft-actions"><Status value={job.state} />{job.kind === 'preflight' && job.state === 'succeeded' && <Button primary onClick={() => void perform(() => sftApi.train(job.id), '训练已进入队列')}>使用此预检开始训练</Button>}{!done(job.state) && <Button disabled={job.cancel} onClick={() => setCancel(true)}><Square size={14} />保存并停止</Button>}</div></div>
    {offline && !done(job.state) && <div className="sft-note">环境心跳中断，最后记录为 {date(worker?.last_seen || job.updated_at)}。正在等待对账，不会重新分配或复制训练任务。</div>}{(job.error || error) && <div className="sft-alert sft-error" role="alert">{job.error || error}</div>}
    <div className="sft-training-layout"><div className="sft-card sft-form"><h3>训练指标</h3>{currentStep !== undefined && <p className="sft-step-count">{currentStep} <span>/ {totalSteps?.total_optimizer_steps ?? totalSteps?.optimizer_steps ?? '未提供'} optimizer steps</span></p>}<LossChart events={events} /><div className="sft-data-numbers"><span><strong>{metrics?.tokens_per_second?.toFixed(1) ?? '未提供'}</strong>tokens / s</span><span><strong>{metrics?.peak_memory !== undefined ? `${metrics.peak_memory.toFixed(2)} GB` : '未提供'}</strong>峰值设备内存</span><span><strong>{metrics?.trained_tokens?.toLocaleString() ?? '未提供'}</strong>已监督 tokens</span></div></div><aside className="sft-card sft-form"><h3>固定配置</h3><dl className="sft-config"><dt>执行器</dt><dd>{job.config.engine}</dd><dt>基础模型</dt><dd>{job.config.model}<small>{job.config.revision}</small></dd><dt>序列 / rank</dt><dd>{job.config.sequence_length} / {job.config.rank}</dd><dt>学习率</dt><dd>{job.config.learning_rate}</dd><dt>梯度累积</dt><dd>{job.config.gradient_accumulation}</dd><dt>预算</dt><dd>{job.config.max_steps} steps / {job.config.max_seconds / 60} 分钟</dd><dt>监督</dt><dd>最终本人回复</dd><dt>恢复语义</dt><dd>{job.config.resume_mode === 'full_state' ? '完整状态恢复' : job.config.resume_mode === 'weights_only' ? '从权重继续，重新建立优化器' : '全新任务'}</dd></dl></aside></div>
    <section className="sft-card sft-form"><h3>产物与恢复点</h3>{!artifacts.length ? <p className="sft-muted">尚无已上传且通过校验的产物。未提交完整 manifest 的文件不会显示为成功产物。</p> : artifacts.map(a => <div className="sft-artifact" key={a.id}><div><h4>{a.name} · {bytes(a.size)}</h4><p className="sft-hash">SHA-256 {a.sha256}</p><p className="sft-muted">{a.resume === 'full_state' ? '包含优化器、调度器、随机状态与训练进度' : a.resume === 'weights_only' ? '只恢复权重，重新建立优化器与进度' : '不支持恢复'}</p></div><div className="sft-actions"><ArtifactDownload artifact={a} />{job.kind === 'train' && done(job.state) && a.resume !== 'none' && <Button onClick={() => void perform(() => sftApi.resume(job.id, a), '继续训练的任务已进入队列')}>{a.resume === 'full_state' ? '完整状态恢复' : '从权重继续'}</Button>}</div></div>)}</section>
    <details className="sft-card sft-details"><summary>阶段、日志与事件（{events.length}）</summary><div className="sft-event-log">{events.map(e => <div key={e.seq}><span>{e.seq} · {date(e.created_at)} · {e.type}</span><code>{JSON.stringify(e.data)}</code></div>)}</div></details>
    <Dialog open={cancel} title="保存并停止此任务" onClose={() => setCancel(false)}><div className="sft-page sft-form"><p>worker 将在安全位置保存并退出。只有收到实际退出回执后，任务才会显示为已停止；保存超时将保留最近有效恢复点。</p><Button primary onClick={() => void perform(async () => { await sftApi.cancel(job.id); setCancel(false); }, '已发送停止请求，正在等待 worker 确认')}>请求保存并停止</Button></div></Dialog>
  </section>;
}

function Evaluations({ jobs, models }: { jobs: SFTJob[]; models: SFTModel[] }) {
  const { privacyMode } = usePrivacyMode();
  const { perform } = useUI(); const [selected, setSelected] = useState(''), [evaluation, setEvaluation] = useState<SFTEvaluation>(), [dimension, setDimension] = useState('style'), [index, setIndex] = useState(0), [error, setError] = useState('');
  const list = jobs.filter(j => j.kind === 'evaluate');
  const reload = useCallback(async () => { if (!selected) return; const result = await sftApi.evaluation(selected); setEvaluation(result); }, [selected]);
  useEffect(() => { let active = true; if (selected) void sftApi.evaluation(selected).then(r => { if (active) { setEvaluation(r); setIndex(0); } }).catch(e => setError(e.message)); else setEvaluation(undefined); return () => { active = false; }; }, [selected, jobs.find(j => j.id === selected)?.state]);
  const sample = evaluation?.cases[index];
  return <section className="sft-form"><div className="sft-section-heading"><div><h2>效果评测</h2><p>使用同一冻结测试集、固定采样配置，隐藏模型名称进行 A/B 人评。真实目标回复不会注入模型输入。</p></div></div><div className="sft-card sft-form"><h3>开始一次固定测试集评测</h3><div className="sft-row"><Select aria-label="待评测模型" placeholder="选择训练成功的模型" options={[{ value: '', label: '选择训练成功的模型', disabled: true }, ...models.map(m => ({ value: m.id, label: `${m.config.model} · ${short(m.id)}` }))]} value="" onValueChange={run => void perform(async () => { const job = await sftApi.evaluate(run); setSelected(job.id); }, '评测已进入队列，需等待训练或推理服务释放资源')} /></div><p className="sft-muted">最多 50 条固定测试样本。不使用外部评审 API。重复查看测试结果后继续调参，会削弱结果的独立性。</p></div>{error && <p role="alert" className="sft-error-text">{error}</p>}
    {!list.length ? <Empty title="完成训练后，再与原模型比较">优先比较回复风格和帮助程度；低 loss 不等于模型更适合你。</Empty> : <Field label="评测记录"><Select value={selected} onValueChange={setSelected} options={[{ value: '', label: '选择一次评测' }, ...list.map(j => ({ value: j.id, label: `${date(j.created_at)} · ${short(j.id)} · ${stateNames[j.state]}` }))]} /></Field>}
    {evaluation && evaluation.job.state !== 'succeeded' && <div className="sft-card"><Status value={evaluation.job.state} /><p className="sft-muted">{evaluation.job.error || 'worker 将依次运行基础模型与微调模型。完成后可进行人工盲测。'}</p></div>}
    {evaluation?.summary && <div className="sft-card sft-form"><h3>{evaluation.sample_count} 条测试样本的描述性比较</h3><p className="sft-muted">{evaluation.summary.evidence}</p><div className="sft-table-scroll"><table><thead><tr><th>指标</th><th>基础模型</th><th>微调模型</th></tr></thead><tbody>{[['holdout_loss', 'Holdout loss'], ['mean_length', '平均回复长度'], ['empty', '空回复数量'], ['repeated', '明显重复数量']].map(([key, label]) => <tr key={key}><td>{label}</td><td>{evaluation.summary?.[`baseline_${key}`] ?? '未提供'}</td><td>{evaluation.summary?.[`tuned_${key}`] ?? '未提供'}</td></tr>)}</tbody></table></div></div>}
    {sample && <div className="sft-card sft-form"><div className="sft-row"><h3>盲测 {index + 1} / {evaluation!.cases.length}</h3><Select aria-label="评价维度" value={dimension} onValueChange={setDimension} options={[{ value: 'style', label: '更像我的表达方式' }, { value: 'helpful', label: '更有帮助' }]} /></div><div className="sft-context">{sample.messages.map((m, i) => <p key={i} className={privacyMode ? 'privacy-blur' : undefined}><span>{m.role === 'user' ? '对方' : m.role === 'assistant' ? '我的历史回复' : '系统'}：</span>{m.content}</p>)}</div><div className="sft-ab-grid">{(['a', 'b'] as const).map(side => <article className="sft-answer" key={side}><h4>回复 {side.toUpperCase()} {sample.voted ? `· ${sample[`${side}_name`]}` : ''}</h4><p className={privacyMode ? 'privacy-blur' : undefined}>{sample[side] || '此模型未生成有效回复'}</p><Button primary={!sample.voted} disabled={sample.voted} onClick={() => void perform(async () => { await sftApi.vote(selected, sample.id, side, dimension); await reload(); })}>{sample.voted ? sample.vote?.choice === side ? '已选择' : '已揭晓' : `选择 ${side.toUpperCase()}`}</Button></article>)}</div>{sample.errors.some(Boolean) && <p className="sft-error-text">存在推理错误，此样本不应作为正常偏好比较。</p>}{sample.leakage?.length > 0 && <p className="sft-note">检测到可能复现较长训练原文，请检查：{sample.leakage.join('；')}</p>}{sample.voted && <p className={`sft-muted ${privacyMode ? 'privacy-blur' : ''}`}>原始目标回复：{sample.reference}</p>}<div className="sft-row"><Button disabled={sample.voted} onClick={() => void perform(async () => { await sftApi.vote(selected, sample.id, 'tie', dimension); await reload(); })}>平局 / 没有明显偏好</Button><div className="sft-actions"><Button disabled={index === 0} onClick={() => setIndex(index - 1)}>上一条</Button><Button disabled={index + 1 >= evaluation!.cases.length} onClick={() => setIndex(index + 1)}>下一条</Button></div></div></div>}
  </section>;
}

function Models({ project, models, deployments, jobs }: { project: string; models: SFTModel[]; deployments: SFTDeployment[]; jobs: SFTJob[] }) {
  const { privacyMode } = usePrivacyMode();
  const { perform } = useUI(); const [cleanup, setCleanup] = useState<Awaited<ReturnType<typeof sftApi.cleanupPreview>>>(); const chatAbort = useRef<AbortController>(); const [partial, setPartial] = useState(''); const [chatting, setChatting] = useState<SFTDeployment>(), [messages, setMessages] = useState<SFTMessage[]>([]), [input, setInput] = useState(''), [confirm, setConfirm] = useState<{ id: string; action: 'default' | 'stop' }>();
  return <section className="sft-form"><div className="sft-section-heading"><div><h2>模型版本与接入</h2><p>适配器绑定基础模型、tokenizer 和模板。服务通过健康和流式检查后才可接入，不会自动更换默认配置。</p></div><Button onClick={() => void perform(async () => setCleanup(await sftApi.cleanupPreview(project)))}>清理失败任务文件</Button></div>{!models.length ? <Empty title="还没有训练完成的模型">训练成功后，适配器、来源版本和恢复能力会显示在这里。</Empty> : models.map(m => { const deployment = deployments.find(d => d.run_id === m.id && !['stopped', 'failed'].includes(d.state)); const evaluated = jobs.some(j => j.kind === 'evaluate' && j.config.parent_run === m.id && j.state === 'succeeded'); return <article key={m.id} className="sft-card sft-form"><div className="sft-row"><div><h3>{m.config.model}</h3><p className="sft-muted">版本 {short(m.id)} · {date(m.created_at)} · {m.config.engine} · {m.config.preset === 'validation' ? '短训验证，仅供试用' : '标准训练'}</p></div><Status value={deployment?.state || 'succeeded'} /></div><p className="sft-hash">基础 revision {m.config.revision}</p><p className="sft-muted">{evaluated ? '已完成固定测试集比较，仍需结合人工评价决定。' : '尚未完成评测，建议先到评测页比较。'} {m.config.engine === 'mlx' ? 'MLX adapter' : 'PEFT adapter'} 不能直接视为通用 GGUF / Ollama 模型。</p><div className="sft-actions">{!deployment ? <Button primary onClick={() => void perform(() => sftApi.deploy(m.id), '推理启动任务已提交，健康检查通过后才会显示在线')}>启动试用服务</Button> : <><Button disabled={deployment.state !== 'online'} onClick={() => { setChatting(deployment); setMessages([]); setPartial(''); }}>试聊</Button>{!deployment.profile_id ? <Button primary disabled={deployment.state !== 'online'} onClick={() => void perform(() => sftApi.connect(deployment.id), '已创建独立模型配置，可在 WeLink 模型选择器中试用')}>接入 WeLink</Button> : <><Button disabled={deployment.state !== 'online'} onClick={() => setConfirm({ id: deployment.id, action: 'default' })}>设为默认</Button><Button disabled={!deployment.previous_profile} onClick={() => void perform(() => sftApi.rollback(deployment.id), '已恢复之前的默认模型配置')}>回滚默认配置</Button></>}<Button onClick={() => setConfirm({ id: deployment.id, action: 'stop' })}>停用服务</Button></>}</div>{m.artifacts.map(a => <div className="sft-artifact" key={a.id}><div><h4>{a.name}</h4><p className="sft-hash">{a.sha256}</p></div><ArtifactDownload artifact={a} /></div>)}</article>; })}
    <Dialog open={!!cleanup} title="清理失败任务文件" onClose={() => setCleanup(undefined)}><div className="sft-page sft-form"><p>只清理本项目控制端的未引用失败产物和过期的未完成上传。成功模型、冻结数据、被后续任务引用的恢复点和 worker 缓存会保留。</p>{cleanup?.items.map(item => <div key={item.id} className="sft-artifact"><div><h4>{short(item.job_id)} / {item.name} · {bytes(item.size)}</h4><p className="sft-muted">{item.reason}</p></div></div>)}<p>{cleanup?.items.length ? `共 ${cleanup.items.length} 个文件，可释放 ${bytes(cleanup.bytes)}。此操作无法撤销。` : '没有可清理的文件。'}</p><Button primary disabled={!cleanup?.items.length} onClick={() => void perform(async () => { if (!cleanup) return; await sftApi.cleanup(project, cleanup.hash); setCleanup(undefined); }, '未引用的失败文件已清理')}>确认清理</Button></div></Dialog>
    <Dialog open={!!chatting} title="试聊训练模型" onClose={() => { chatAbort.current?.abort(); setChatting(undefined); }} className="!w-[min(96vw,48rem)]"><div className="sft-page sft-form"><p className="sft-muted">试聊不会自动写入训练集。服务异常会明确报错，不会静默切换模型。</p><div className="sft-chat-history">{messages.map((m, i) => <div className={`sft-message ${m.role === 'assistant' ? 'sft-target' : ''}`} key={i}><span>{m.role === 'assistant' ? '训练模型' : '我'}</span><p className={privacyMode ? 'privacy-blur' : undefined}>{m.content}</p></div>)}{partial && <div className="sft-message sft-target"><span>训练模型 · 正在回复</span><p className={privacyMode ? 'privacy-blur' : undefined}>{partial}</p></div>}</div><Field label="试聊消息"><textarea value={input} maxLength={8000} rows={3} onChange={e => setInput(e.target.value)} placeholder="输入一段你平时会收到的消息…" /></Field><Button primary disabled={!input.trim()} onClick={() => void perform(async () => { if (!chatting) return; const next: SFTMessage[] = [...messages, { role: 'user', content: input }]; chatAbort.current = new AbortController(); let reply = ''; setPartial(''); try { await sftApi.streamChat(chatting.id, next, text => { reply += text; setPartial(reply); }, chatAbort.current.signal); if (!reply.trim()) throw new Error('模型没有返回有效回复'); setMessages([...next, { role: 'assistant', content: reply }]); setInput(''); } finally { setPartial(''); } })}>发送</Button></div></Dialog>
    <Dialog open={!!confirm} title={confirm?.action === 'default' ? '设为 WeLink 默认模型' : '停用推理服务'} onClose={() => setConfirm(undefined)}><div className="sft-page sft-form"><p>{confirm?.action === 'default' ? '此模型将用于默认的 AI 功能。当前默认配置会被记录，可以从工作台回滚。' : 'worker 确认进程已退出后才会释放资源。已有模型配置会保留，但调用会提示服务离线；如它是默认项，请先回滚。'}</p><Button primary onClick={() => void perform(async () => { if (!confirm) return; await sftApi[confirm.action](confirm.id); setConfirm(undefined); }, confirm?.action === 'default' ? '已设为默认，可在此回滚' : '已请求停止推理服务')}>确认{confirm?.action === 'default' ? '设为默认' : '停用'}</Button></div></Dialog>
  </section>;
}

function ArtifactDownload({ artifact }: { artifact: SFTArtifact }) {
  const { perform } = useUI(); const [open, setOpen] = useState(false);
  return <><Button onClick={() => artifact.size > 256 * 1024 ** 2 ? setOpen(true) : void perform(() => sftApi.download(`/artifacts/${artifact.id}/download`, artifact.name))}><Download size={14} />下载</Button><Dialog open={open} title="下载大型产物" onClose={() => setOpen(false)}><div className="sft-page sft-form"><p>此文件为 {bytes(artifact.size)}。请在产物所属的训练机运行以下命令，流式传输并校验 SHA-256，避免浏览器把完整检查点载入内存。</p><pre className="sft-code">{`welink-sft download --id ${artifact.id} --sha256 ${artifact.sha256} --output ${artifact.name}`}</pre><p className="sft-muted">使用已经配对的 worker 环境；如设置了自定义目录，在命令前加 --root。原始文件也保存在该训练任务的 worker 本地目录。传输支持续传，不需要在命令中写密钥。</p></div></Dialog></>;
}
